// Только просмотр; запросы записи всё равно заблокированы (сохранение правил действует на все семьи).
import { test, expect } from '@playwright/test';
import path from 'node:path';
import { SCENARIOS, blockRuleWrites, field, saveButton, cancelConfirmIfShown } from '../helpers/expert';

test.use({ storageState: path.join(__dirname, '../../../auth/expert.json') });

test.describe('Экран «חוקי זיהוי» — эксперт', () => {
  test.afterEach(async ({ page }) => { await cancelConfirmIfShown(page); });

  test('Эксперт: «חוקי זיהוי» под «מוצרים לבריכה», экран с текущими значениями и тегом «זמני» #89216b @desktop @prod-safe', async ({ page }) => {
    const writes = await blockRuleWrites(page);

    // 1. «חשבון»: строка «חוקי זיהוי» сразу под «מוצרים לבריכה» и выше «יציאה מהחשבון» — AC2
    await page.goto('/account');
    const products = page.getByText('מוצרים לבריכה', { exact: true }).filter({ visible: true });
    const rules = page.getByText('חוקי זיהוי', { exact: true }).filter({ visible: true });
    const logout = page.getByText('יציאה מהחשבון', { exact: true }).filter({ visible: true });
    await expect(rules).toBeVisible();
    const [p, r, l] = [await products.boundingBox(), await rules.boundingBox(), await logout.boundingBox()];
    expect(r!.y, '«חוקי זיהוי» ниже «מוצרים לבריכה»').toBeGreaterThan(p!.y);
    expect(r!.y - p!.y, 'следующая строка, без строк между ними').toBeLessThan(p!.height + 80);
    expect(r!.y, '«חוקי זיהוי» выше «יציאה מהחשבון»').toBeLessThan(l!.y);

    // 2. Нажать → экран /account/expert
    await rules.click();
    await expect(page).toHaveURL(/\/account\/expert/);
    await expect(page.getByText('איך זה עובד', { exact: true }).filter({ visible: true })).toBeVisible();

    // Версия и тег «זמני» — AC2
    await expect(page.getByText(/גרסה נוכחית:/).filter({ visible: true })).toBeVisible();
    await expect(page.getByText('זמני', { exact: true }).filter({ visible: true })).toBeVisible();

    // Текущие значения 5 сценариев: числа, не пусто; у каждого подсказка с «טווח» — AC2, коммент #a1f74f
    await expect(page.getByText('תרחישי סכנה וספי זמן', { exact: true }).first()).toBeVisible();
    for (const s of SCENARIOS) {
      await expect(field(page, s), s).toHaveValue(/^\d+(\.\d+)?$/);
    }
    expect(await page.getByText(/טווח:/).count(), 'подсказки с диапазоном').toBeGreaterThanOrEqual(SCENARIOS.length);

    // Остальные разделы экрана (коммент #a1f74f)
    for (const t of ['מתי מופעלת אזעקה', 'בכל התרחישים', 'רק ראש מתחת למים והיעלמות', 'משחק רגיל או מצוקה', 'סיכום מקצועי', 'מה נקבע ולמה', 'הערכים אושרו על ידי איש מקצוע']) {
      await expect(page.getByText(t, { exact: true }).first(), t).toBeAttached();
    }
    await expect(saveButton(page)).toBeVisible();
    expect(writes.saveCalls).toBe(0);
  });
});
